        urllib.parse.quote(object_key, safe=""), urllib.parse.quote(record_id, safe=""))
    return record_from(request(runtime, "GET", path, session=session))



def resolve_customer_storage(database):
    """Resolve one physical customer relation using parameterized metadata SELECTs."""
    rows = database.query(
        "SELECT table_name, column_name FROM information_schema.columns "
        "WHERE table_schema=DATABASE() AND column_name IN (%s,%s,%s) "
        "ORDER BY table_name, ordinal_position",
        ("id", "source_lead_id", "company_name"),
    )
    columns_by_table = {}
    for row in rows:
        normalized_row = {str(key).lower(): value for key, value in row.items()}
        table = str(normalized_row.get("table_name") or "")
        column = str(normalized_row.get("column_name") or "")
        if table and column:
            columns_by_table.setdefault(table, set()).add(column)
    candidates = [
        table for table, columns in columns_by_table.items()
        if {"id", "source_lead_id", "company_name"}.issubset(columns)
    ]
    exact = [table for table in candidates if table.lower() == "customer"]
    if len(exact) == 1:
        selected = exact[0]
    elif len(candidates) == 1:
        selected = candidates[0]
    else:
        raise core.HarnessError(
            "canonical MySQL cohort did not resolve exactly one customer persistence relation")
    return {
        "table": selected,
        "id_column": "id",
        "lead_column": "source_lead_id",
        "company_column": "company_name",
    }


def normalized_database_value(value):
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, decimal.Decimal):
        return format(value, "f")
    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        return value.isoformat()
    if isinstance(value, bytes):
        return {"bytes": len(value), "sha256": hashlib.sha256(value).hexdigest()}
    if isinstance(value, dict):
        return {str(key): normalized_database_value(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [normalized_database_value(item) for item in value]
    return str(value)


def database_customer_rows(database, storage, lead_id):
    relation = database.relation(storage["table"])
    lead_column = database.identifier(storage["lead_column"])
    id_column = database.identifier(storage["id_column"])
    sql = "SELECT * FROM %s WHERE %s=%s ORDER BY %s" % (
        relation, lead_column, database.placeholder(), id_column)
    rows = database.query(sql, (lead_id,))
    return [
        {str(key): normalized_database_value(value) for key, value in row.items()}
        for row in rows
    ]


def durable_closure(runtime, director, database, storage, approval_id, lead_id):
    approval = get_record(runtime, director, "conversion_approval", approval_id)
    lead = get_record(runtime, director, "lead", lead_id)
    customers = database_customer_rows(database, storage, lead_id)
    closure = {
        "approval": core.durable_record_snapshot(approval),
        "lead": core.durable_record_snapshot(lead),
        "customer_database_rows": customers,
    }
    return closure, sha256_json(closure)


def principal_evidence(session):
    context = session.get("principal_context") or {}
    safe_contexts = []
    for item in context.get("request_contexts") or []:
        safe = {}
        for key in (
            "subject_kind", "user_id", "workspace_id", "surface_key", "business_profile_key",
            "business_profile_id", "workforce_profile_id", "organization_id", "organization_unit_id",
        ):
            if key in item and item[key] not in (None, ""):
                safe[key] = item[key]
        headers = item.get("canonical_request_headers") or {}
        safe["canonical_header_names"] = sorted(headers)
        safe["canonical_header_values_sha256"] = sha256_json(headers)
        safe_contexts.append(safe)
    return {
        "contract_version": context.get("contract_version"),
        "known": context.get("known"),
        "user_id": context.get("user_id"),
        "workspace_id": context.get("workspace_id"),
        "role_keys": sorted(context.get("role_keys") or []),
        "request_contexts": safe_contexts,
    }


def workforce_context(sessions, user_id):
    authenticated = sessions.session(user_id)
    contexts = [
        item for item in authenticated["principal_context"].get("request_contexts") or []
        if item.get("subject_kind") == "workforce"
    ]
    if len(contexts) != 1:
        raise core.HarnessError(
            "authenticated principal-context did not return exactly one workforce context")
    workforce_profile_id = contexts[0].get("workforce_profile_id")
    if not isinstance(workforce_profile_id, str) or not workforce_profile_id:
        raise core.HarnessError(
            "authenticated workforce context lacks a formal workforce_profile_id selector")
    return sessions.context(
        user_id, "workforce", workforce_profile_id=workforce_profile_id)


